            Write-Host "  [X] $($mod.Path) - REQUIRED, NOT FOUND" -ForegroundColor Red
            $failedModules += $mod.Path
        } else {
            Write-Host "  [-] $($mod.Path) - Optional, skipped" -ForegroundColor DarkGray
        }
