    $db = [Text.Encoding]::UTF8.GetBytes($Data)
    $hmac = New-Object Security.Cryptography.HMACSHA256
    $hmac.Key = $kb
    return ([BitConverter]::ToString($hmac.ComputeHash($db))) -replace '-', ''
