$script:GhostPatterns = @(
    "GhostWhisper", "GhostKey", "WraithTap", "Wormhole", "Phantom",
    "ghost_", ".ghost", "ghostkernel", "PhantomHook", "GhostBrowser",
    "GhostDesktop", "GhostSeal", "BLETrigger", "ExorcistMode"
