    "successfully authenticated",
    "Unable to authenticate",
    "Bill Dispenser Present Cash",
    "Dispensed Amount",
    "JackpotDispenseProcessingView",
    "Cash Collected",
    "GhostResidency",
    "GHOST_TAG",
    "ghostTag"
