        if ($fileSize -eq 0) {
            Remove-Item $FilePath -Force -ErrorAction SilentlyContinue
            return
        }

        for ($pass = 0; $pass -lt $Passes; $pass++) {
            $patterns = @(
                { New-Object byte[] $args[0] },
                { $b = New-Object byte[] $args[0]; [Security.Cryptography.RandomNumberGenerator]::Fill($b); $b },
                { [byte[]](@(0x00) * $args[0]) },
                { [byte[]](@(0xFF) * $args[0]) }
            )

