            "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Logs",
            "${env:ProgramFiles}\Google\Chrome Remote Desktop\Logs",
            "${env:ProgramFiles(x86)}\Google\Chrome Remote Desktop\Logs"
