            if (Test-Path $regPath) {
                Remove-Item -Path $regPath -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        Write-Log "GhostBrowser traces cleaned" "SUCCESS"

    } catch {
        Write-Log "GhostBrowser cleanup error: $_" "WARN"
    }
